First write
    \begin{align*}
        \langle AP_1,BP_2\rangle&=\langle (A-\overline{A})P_1+\overline{A}P_1,(B-\overline{B})P_2+\overline{B}P_2\rangle\\
        &=\langle (A-\overline{A})P_1,\overline{B}P_2\rangle+\langle \overline{A}P_1,(B-\overline{B})P_2\rangle+\langle (A-\overline{A})P_1,(B-\overline{B})P_2\rangle+\langle \overline{A}P_1,\overline{B}P_2\rangle.
    \end{align*}
    Then the inequality follows from the triangle inequality, the Cauchy-Schwarz inequality and the submultiplicativity of $\|.\|$:
    \begin{align*}
    |\langle AP_1,BP_2\rangle-\langle \overline{A}P_1,\overline{B}P_2\rangle|    &\leq\Big|\langle (A-\overline{A})P_1,\overline{B}P_2\rangle\Big|+\Big|\langle \overline{A}P_1,(B-\overline{B})P_2\rangle\Big|+\Big|\langle (A-\overline{A})P_1,(B-\overline{B})P_2\rangle\Big|\\
    & \hspace{-1cm} \leq\|(A-\overline{A})P_1\|\cdot \|\overline{B}P_2\|+\|\overline{A}P_1\|\cdot \|(B-\overline{B})P_2\|+\|(A-\overline{A})P_1\|\cdot \|(B-\overline{B})P_2\|\\
    & \hspace{-1cm} \leq \|P_1\|\cdot \|P_2\|\cdot \Big( \|A-\overline{A}\|\cdot \|\overline{B}\| +  \|\overline{A}\|\cdot \|B-\overline{B}\|+\|A-\overline{A}\|\cdot \|B-\overline{B}\|\Big). \quad \qedhere
    \end{align*}

Exactly the same proof as the one for \cref{lem:scalarprodbars} yields
    \begin{align*}
    |\langle AP_1,AP_2\rangle-\langle BP_1,BP_2\rangle|  \leq  \|P_1\|\cdot \|P_2\|\cdot \|A-B\|\cdot \bigg( 2\|B\| + \|A-B\|\bigg)
    \end{align*}
    Exchanging $A$ and $B$, however, also gives the same inequality with $2\|A\|$ instead of $2\|B\|$. Taking the arithmetic mean of these two upper bounds produces the desired symmetric inequality.

Let $\theta, \varphi \in \mathbb{R}$, $\varepsilon>0$ and set $M \coloneqq M(\theta, \varphi)$. Three points $P_1, P_2, P_3 \in \mathbb{R}^3$ with $\|P_1\|,\|P_2\|,\|P_3\| \leq 1$ are called \emph{$\varepsilon$-spanning for $(\theta, \varphi)$} if it holds that:
\begin{align*}
    \langle R(\pi/2) M P_1,M P_{2}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon),\\
    \langle R(\pi/2) M P_2,M P_{3}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon),\\
    \langle R(\pi/2) M P_3,M P_{1}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon).
\end{align*}

For any $v\in \mathbb{R}^n$ we have
    \begin{align*}
        \|Av\|^2 &=\sum_{i=1}^m \left(\sum_{j=1}^na_{i,j}v_j\right)^2 \leq \sum_{i=1}^m\left(\sum_{j=1}^n \delta |v_j|\right)^2 = \delta^2 m\left(\sum_{j=1}^n |v_j|\right)^2 \leq \delta^2 m n \|v\|^2
    \end{align*}
    using the Cauchy-Schwarz inequality. Dividing by $\|v\|$ and taking the square root proves the claim.

Let $\theta, \varphi \in \mathbb{Q} \cap [-4,4]$ and $M_{\mathbb{Q}} \coloneqq M_{\mathbb{Q}}(\theta, \varphi)$. Three points $\widetilde{P}_1, \widetilde{P}_2, \widetilde{P}_3 \in \mathbb{Q}^3$ with $\|\widetilde{P}_1\|, \|\widetilde{P}_2\|, \|\widetilde{P}_3\| \leq 1+\kappa$ are called \emph{$\varepsilon$-$\kappa$-spanning for $(\theta, \varphi)$} if it holds that:
\begin{align*}
    \langle R(\pi/2) M_{\mathbb{Q}} \widetilde{P}_1,M_{\mathbb{Q}} \widetilde{P}_{2}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon) + 6\kappa,\\
    \langle R(\pi/2) M_{\mathbb{Q}} \widetilde{P}_2,M_{\mathbb{Q}} \widetilde{P}_{3}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon) + 6\kappa,\\
    \langle R(\pi/2) M_{\mathbb{Q}} \widetilde{P}_3,M_{\mathbb{Q}} \widetilde{P}_{1}\rangle > 2 \varepsilon(\sqrt{2} + \varepsilon) + 6\kappa.
\end{align*}

Let $P,Q \in \mathbb{R}^3$ with $\|P\|,\|Q\|\leq 1$ and $\widetilde{P},\widetilde{Q}$ some respective $\kappa$-rational approximations. Moreover, let $\alpha, \theta, \varphi \in \mathbb{R} \in [-4,4]$ and set $X = X(\theta, \varphi)$, $X_{\mathbb{Q}} = X_{\mathbb{Q}}(\theta, \varphi)$ as well as $M = M(\theta, \varphi)$, $M_{\mathbb{Q}} = M_{\mathbb{Q}}(\theta, \varphi)$. Then
    \begin{align}
        |\langle X, P \rangle - \langle X_{\mathbb{Q}}, \widetilde{P} \rangle| & \leq 3 \kappa, \\
        |\langle MP, MQ \rangle - \langle M_{\mathbb{Q}} \widetilde{P}, M_{\mathbb{Q}}\widetilde{Q} \rangle| & \leq 5 \kappa, \\
        |\| M Q \| - \| M_{\mathbb{Q}}\widetilde{Q} \| | & \leq 3 \kappa. \end{align}

conclusions:
\begin{align}
        |\langle X, P \rangle - \langle X_{\mathbb{Q}}, \widetilde{P} \rangle| & \leq 3 \kappa, \label{eq:boundskappa3.1}\\
        |\langle MP, MQ \rangle - \langle M_{\mathbb{Q}} \widetilde{P}, M_{\mathbb{Q}}\widetilde{Q} \rangle| & \leq 5 \kappa, \label{eq:boundskappa3.3}\\
        |\| M Q \| - \| M_{\mathbb{Q}}\widetilde{Q} \| | & \leq 3 \kappa.\label{eq:boundskappa3.2}
    \end{align}

\[
    |\| R(\alpha) M P - \overline{M} Q\|- \| R_{\mathbb{Q}}(\alpha) M_{\mathbb{Q}} \widetilde{P} - \overline{M}_{\mathbb{Q}} \widetilde{Q}\| | \leq 6 \kappa.\label{eq:boundskappa3.4} 
    \]

nodes.statement:
Generally speaking, in order to prove that a solution for any solid $\mathbf{P}$ does not exist within any given five dimensional interval for $[\overline{\theta}_1, \overline{\varphi}_1, \overline{\theta}_2, \overline{\varphi}_2, \overline{\alpha}] \pm \varepsilon \subseteq \mathbb{R}^5$, we can establish 3 (recursive) options:
\begin{itemize}
    \item [(I)] Apply the (rational) global theorem (\cref{thm:global}),
    \item [(II)] Apply the (rational) local theorem (\cref{thm:local}),
    \item [(III)] Subdivide the interval into smaller intervals, and for each of them again apply one of (I)--(III).
\end{itemize}

Similarly to $\mathbf{NOP}$, we start by setting three points $D_1,D_2,D_3\in \mathbb{Q}^3$ to be:
\[
    D_1\coloneqq
        \frac{1}{5861}
        \begin{pmatrix} 
        {3939} \\ 0 \\ {4340} 
        \end{pmatrix},
    \qquad
    D_2\coloneqq \frac{1}{10^4}
        \begin{pmatrix} 
        7855 \\ 4178 \\ 4484
        \end{pmatrix},
    \qquad
    D_3\coloneqq
        \frac{1}{10^4}
        \begin{pmatrix} 
        9526 \\ 2057 \\ 1102
        \end{pmatrix}.
\]

Namely, for every row in the solution tree which has noteType=1 we must perform the following operations (additionally to 1. and 2. above):
\begin{enumerate}
    \setcounter{enumi}{2}
    \item Set $w = ($wx\_numerator/w\_denominator, wy\_numerator/w\_denominator$) \in \mathbb{Q}^2$ and check that $\|w\|^2 = w_1^2 + w_2^2=1$.
    \item Set $\widetilde{S}$ to be the rationally approximated point corresponding to the index given in column~S\_index.
    \item Compute $\overline{M_1}$, $\overline{M_2}$, $\overline{M_1}^\theta$, $\overline{M_1}^\varphi$, $\overline{M_2}^\theta$, $\overline{M_2}^\varphi \in \mathbb{Q}^{2 \times 3}$ and $R_{\mathbb{Q}}(\overline{\alpha}), R'_{\mathbb{Q}}(\overline{\alpha}) \in \mathbb{Q}^{2 \times 2}$ as in \cref{thm:global_rational}.
    \item Compute $G^{\mathbb{Q}} \in \mathbb{Q}$ and $H_{P}^{\mathbb{Q}} \in \mathbb{Q}$ for all $P \in \widetilde{\mathbf{NOP}}$ as in \cref{thm:global_rational}.
    \item Verify that $G^{\mathbb{Q}} > \max H_{P}^{\mathbb{Q}}$.
\end{enumerate}

We show the equality for $a=x$ only; so we calculate 
    \begin{align*}
        \|R_x(\alpha)-R_x({\overline{\alpha}})\| &= \max_{v_1^2+v_2^2+v_3^2=1}\left\|
    \begin{pmatrix} 
        0 & 0 & 0\\ 
        0 & \cos(\alpha)-\cos(\overline{\alpha}) & -\sin(\alpha)+\sin(\overline{\alpha})\\
        0 & \sin(\alpha)-\sin(\overline{\alpha}) & \cos(\alpha)-\cos(\overline{\alpha})
    \end{pmatrix} 
    \begin{pmatrix} 
        v_1\\
        v_2\\
        v_3
    \end{pmatrix}\right\|\\
    &=\max_{v_2^2+v_3^2=1}\left\|\left(R(\alpha)-R(\overline{\alpha})\right)\begin{pmatrix} 
        v_2\\
        v_3
    \end{pmatrix}\right\|\\
    &=\|R(\alpha)-R(\overline{\alpha})\|.
    \end{align*}

We conclude using Jensen's inequality:
    \begin{align*}
        \frac{\cos(x+y) + \cos(x-y)}{2} = & \frac{f((x+y)^2)+f((x-y)^2)}{2} \\
        & \geq f\left( \frac{(x+y)^2+(x-y)^2}{2} \right) = \cos(\sqrt{x^2+y^2}).
    \end{align*}

Without loss of generality we can assume $|\alpha|,|\beta|\leq 2$, since if the equation is true for $(\alpha,\beta)$, then it is also true for $(2\alpha,2\beta)$ as
    \begin{align*}
    \|R_x(2\alpha)R_y(2\beta)-\mathrm{Id}\| &\leq \|R_x(2\alpha)R_y(2\beta)-R_x(\alpha)R_y(\beta)\|+\|R_x(\alpha)R_y(\beta)-\mathrm{Id}\|\\
    &=2\|R_x(\alpha)R_y(\beta)-\mathrm{Id}\|,
    \end{align*}
    using the triangle inequality and multiplying by $R_x(-\alpha)$ from the left and $R_y(-\beta)$ from the right.

Combining everything we find
\begin{align*}
  \|R_x(\alpha)R_y(\beta)-\text{Id}\| =\|UR_x(\Psi)U^{-1}-\text{Id}\| =\|R_x(\Psi)-\text{Id}\| =\|R_x(\Psi)-R_x(0)\|
    \leq |\Psi|\leq \sqrt{\alpha^2+\beta^2}
\end{align*}
using \cref{lem:RaRa} in the fourth step. \cref{lem:RaRa} also infers that the inequality in this step is strict except for $\Psi = 0$. In this case, however, the inequality in step five is strict except for $\alpha = \beta = 0$.

It follows that
    \begin{align*}
    \|M(\theta, \varphi)-M(\overline{\theta},\overline{\varphi})\| \leq \|Z\|\cdot \|R_y(\varphi) \cdot R_z(-\theta)- R_y(\overline{\varphi}) \cdot R_z(-\overline{\theta})\|
    \end{align*}
    from the sub-multiplicativity of the norm. Using $\|Z\|=1$ and that $R_y(-\varphi), R_z(\theta)$ are orthogonal we obtain
\begin{align*}
    \|M(\theta, \varphi)-M(\overline{\theta},\overline{\varphi})\| \leq \|\text{Id}-R_y(\overline{\varphi}-\varphi)R_z(\theta-\overline{\theta})\|. 
\end{align*}

Altogether, one obtains
    \begin{align*}
      |f(x_1,\dots,x_n)-f(y_1,\dots,y_n)| & = |g(1)-g(0)| \leq |g'(0)|+\int_0^1\int_0^t |g''(s)|\text{d}s\text{d}t\\
      &\leq \varepsilon \sum_{i=1}^n | \partial_{x_i} f(x_1,\dots,x_n)| + \frac{n^2}{2}\varepsilon^2. \qquad \qedhere
    \end{align*}

Multiplying the inequality with $\|S\|$ we get
    \begin{align*}
        |\langle R(a)  M({\overline{\theta}_1,\overline{\varphi}_1})S,w \rangle-\langle R(\alpha) M(\theta_1, \varphi_1)S,w \rangle| & \\
       & \hspace{-6.5cm} \leq \varepsilon\cdot\bigg(|\langle R(\alpha)  M({\overline{\theta}_1,\overline{\varphi}_1})S,w \rangle|+|\langle R(\overline{\alpha})  M^\theta({\overline{\theta}_1,\overline{\varphi}_1})S,w \rangle|+|\langle R(\overline{\alpha})  M^\varphi({\overline{\theta}_1,\overline{\varphi}_1})S,w \rangle|\bigg) +\frac{9}{2}\varepsilon^2\|S\|.
    \end{align*}
    From this and $\|S\|\leq 1$ the inequality (ii) follows.

Exactly the same proof as the one for \cref{lem:scalarprodbars} yields
    \begin{align*}
    |\langle AP_1,AP_2\rangle-\langle BP_1,BP_2\rangle|  \leq  \|P_1\|\cdot \|P_2\|\cdot \|A-B\|\cdot \bigg( 2\|B\| + \|A-B\|\bigg)
    \end{align*}

We apply \cref{lem:absscalar} to $A = M, B = \overline{M}$ and $P_1 = P, P_2 = P-Q$:
\begin{align*}
|\langle {M} P,{M} (P-Q) \rangle - \langle \overline{M} P,\overline{M} (P-Q)\rangle | & \leq \|P\| \cdot \|P - Q\| \cdot \| M - \overline{M} \| \cdot (\|M\| + \|\overline{M}\| + \| M - \overline{M} \|) \\
& \leq 1 \cdot \| P - Q \| \cdot \sqrt{2}\varepsilon \cdot (1 + 1 + \sqrt{2} \varepsilon),
\end{align*}
and observe the claim for the numerator using the triangle inequality. In particular, $\langle {M} P,{M} (P-Q)\rangle > 0$, thus $MP$ and $M(P-Q)$ are non-zero, and the denominator does not~vanish.

First observe that (A$_\varepsilon$) and \cref{lem:XP>0} imply that
    \begin{equation} \langle X(\theta_1, \varphi_1), \overline{P_i} \rangle, \langle X(\theta_2, \varphi_2), \overline{Q_i} \rangle > 0.
    \end{equation}

For fixed $x,y$ every entry of $A(x,y)-A_{\mathbb{Q}}(x,y)$ is of the form
    $a b - \widetilde{a}\widetilde{b}$ for some $a,b\in[-1,1]$ and $|a-\widetilde{a}|,|b-\widetilde{b}|\leq \kappa/7$ by \cref{lem:kappa/7}. This implies that
    \begin{align*}
      |ab-\widetilde{a}\widetilde{b}|&\leq |a b-a\widetilde{b}|+|a \widetilde{b}-\widetilde{a}\widetilde{b}|
      =|a|\cdot |b-\widetilde{b}|+|\widetilde{b}|\cdot |a-\widetilde{a}| \leq 1\cdot \kappa/7+(1+\kappa/7) \cdot \kappa/7 <\kappa/3.
    \end{align*}

Note that all entries of the table are integers, therefore no rounding loss occurs when loading or storing it. 
When talking about \textit{indices of vertices} we refer to the ordering $\mathbf{NOP} = (P_0, \dots, P_{89})$ defined as
\begin{align} P_{k+15i+45 \ell}=(-1)^\ell R_z\left(\frac{2\pi k}{15}\right)C_{i+1}
\quad \text{ for } \quad i \in \{0,1,2\}, \; k \in \{0,\dots,14\}, \; \ell \in \{0,1\},
\end{align}
and $C_1, C_2, C_3 \in \mathbb{Q}^3$ given in \cref{sec:noperthedron}. Moreover, we always assume that $\sigma_{P} = 0$, so we only store~$\sigma_Q \in \{0,1\}$.

The verification of the rational global theorem (\cref{thm:global_rational}) is relatively straightforward. Namely, for every row in the solution tree which has noteType=1 we must perform the following operations (additionally to 1. and 2. above):
\begin{enumerate}
    \setcounter{enumi}{2}
    \item Set $w = ($wx\_numerator/w\_denominator, wy\_numerator/w\_denominator$) \in \mathbb{Q}^2$ and check that $\|w\|^2 = w_1^2 + w_2^2=1$.
    \item Set $\widetilde{S}$ to be the rationally approximated point corresponding to the index given in column~S\_index.
    \item Compute $\overline{M_1}$, $\overline{M_2}$, $\overline{M_1}^\theta$, $\overline{M_1}^\varphi$, $\overline{M_2}^\theta$, $\overline{M_2}^\varphi \in \mathbb{Q}^{2 \times 3}$ and $R_{\mathbb{Q}}(\overline{\alpha}), R'_{\mathbb{Q}}(\overline{\alpha}) \in \mathbb{Q}^{2 \times 2}$ as in \cref{thm:global_rational}.
    \item Compute $G^{\mathbb{Q}} \in \mathbb{Q}$ and $H_{P}^{\mathbb{Q}} \in \mathbb{Q}$ for all $P \in \widetilde{\mathbf{NOP}}$ as in \cref{thm:global_rational}.
    \item Verify that $G^{\mathbb{Q}} > \max H_{P}^{\mathbb{Q}}$.
\end{enumerate}

Note that all steps only use rational numbers, thus in the computer algebra system \href{https://www.sagemath.org/}{SageMath} no rounding loss or precision errors can occur.

Check that $\widetilde{P}_1,\widetilde{P}_2,\widetilde{P}_3$ are $\varepsilon$-$\kappa$-spanning for $(\overline{\theta}_1, \overline{\varphi}_1)$ and that $\widetilde{Q}_1,\widetilde{Q}_2,\widetilde{Q}_3$ are $\varepsilon$-$\kappa$-spanning for $(\overline{\theta}_2, \overline{\varphi}_2)$ by verifying the inequalities in \cref{def:ekspanning}:
